// tb.v: random-stimulus testbench for Mem, generated by tests/unit/test_emit.c.
// Prints the outputs every cycle; test_emit compares them with the Tern simulator.
`timescale 1ns/1ps
module tb;
    reg clk = 1'b0;
    reg rst = 1'b0;
    reg we = 1'b0;
    reg [3:0] waddr = 4'd0;
    reg [15:0] wdata = 16'd0;
    reg [1:0] wmask = 2'd0;
    reg [3:0] raddr = 4'd0;
    reg [3:0] raddr2 = 4'd0;
    reg [2:0] raddr3 = 3'd0;
    reg big_we = 1'b0;
    wire [15:0] rdata;
    wire [15:0] adata;
    wire [7:0] romdata;
    wire [7:0] bigdata;
    wire [7:0] count;
    reg [34:0] stim [0:239];
    integer i;

    Mem dut (
        .clk(clk),
        .rst(rst),
        .we(we),
        .waddr(waddr),
        .wdata(wdata),
        .wmask(wmask),
        .raddr(raddr),
        .raddr2(raddr2),
        .raddr3(raddr3),
        .big_we(big_we),
        .rdata(rdata),
        .adata(adata),
        .romdata(romdata),
        .bigdata(bigdata),
        .count(count)
    );

    task cycle_clk;
        begin
            clk = 1'b1;
            #5;
            clk = 1'b0;
            #5;
        end
    endtask

    task do_reset;
        begin
            rst = 1'b1;
            #1;
            cycle_clk;
            cycle_clk;
            rst = 1'b0;
            #1;
        end
    endtask

    initial begin
        $readmemh("stim.hex", stim);
        #1;
        for (i = 0; i < 240; i = i + 1) begin
            if (i == 0 || i == 120)
                do_reset;
            {we, waddr, wdata, wmask, raddr, raddr2, raddr3, big_we} = stim[i];
            #1;
            $display("D %0d %h %h %h %h %h", i, rdata, adata, romdata, bigdata, count);
            cycle_clk;
        end
        $finish;
    end
endmodule
